using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static partial class Extension05Tools {
static void RoadGrassOnly(){var s=Load("10005a");var folder=W+"/outputs/RoadGrassCorrection";Directory.CreateDirectory(folder);EditorSceneManager.SaveScene(s,folder+"/10005a_before_correction.unity",true);
var original=File.ReadAllLines(W+"/work/grass-original-states.tsv").Select(l=>l.Split('\t')).GroupBy(a=>a[0]).ToDictionary(g=>g.Key,g=>g.Select(a=>a[1]).Distinct().Single()=="1");
var all=All(s);var grasses=all.Where(t=>FineGrass(t)&&original.ContainsKey(t.name)).ToArray();Undo.RecordObjects(grasses.Select(t=>(UnityEngine.Object)t.gameObject).ToArray(),"Restore meadow grass and clear yellow dirt road");int restored=0;foreach(var t in grasses){bool state=original[t.name];if(state&&!t.gameObject.activeSelf)restored++;t.gameObject.SetActive(state);}
var terrain=all.Select(t=>t.GetComponent<Terrain>()).First(t=>t&&t.gameObject.activeInHierarchy);var td=terrain.terrainData;var layers=td.terrainLayers;int dirt=Array.FindIndex(layers,l=>l&&l.diffuseTexture&&l.diffuseTexture.name=="T_Ground_01_BC");if(dirt<0)throw new Exception("Yellow dirt terrain layer not found");var alpha=td.GetAlphamaps(0,0,td.alphamapWidth,td.alphamapHeight);
Func<float,float,float> weight=(x,z)=>{float u=(x-terrain.transform.position.x)/td.size.x;float v=(z-terrain.transform.position.z)/td.size.z;if(u<0||u>1||v<0||v>1)return 0;float fx=u*(td.alphamapWidth-1),fz=v*(td.alphamapHeight-1);int ix=Mathf.FloorToInt(fx),iz=Mathf.FloorToInt(fz);return Mathf.Lerp(Mathf.Lerp(alpha[iz,ix,dirt],alpha[iz,Mathf.Min(ix+1,td.alphamapWidth-1),dirt],fx-ix),Mathf.Lerp(alpha[Mathf.Min(iz+1,td.alphamapHeight-1),ix,dirt],alpha[Mathf.Min(iz+1,td.alphamapHeight-1),Mathf.Min(ix+1,td.alphamapWidth-1),dirt],fx-ix),fz-iz);};
int removed=0;var report=new List<string>();foreach(var t in grasses.Where(t=>t.gameObject.activeInHierarchy)){var b=B(t.gameObject);float max=weight(b.center.x,b.center.z);float dx=Mathf.Min(.5f,b.extents.x*.6f),dz=Mathf.Min(.5f,b.extents.z*.6f);foreach(float x in new[]{-dx,0,dx})foreach(float z in new[]{-dz,0,dz})max=Mathf.Max(max,weight(b.center.x+x,b.center.z+z));if(max>=.30f){t.gameObject.SetActive(false);removed++;report.Add(t.name+" road weight="+max+" position="+t.position);}}
EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);report.Insert(0,"Restored="+restored+"; Road grass cleared="+removed+"; Meadow grass active="+grasses.Count(t=>t.gameObject.activeInHierarchy)+"; Saved="+!s.isDirty);File.WriteAllLines(folder+"/Result.txt",report);File.WriteAllText(W+"/work/roadgrass-result.txt",report[0]);}
}
